"""For the given event_list, determine whether physical
    or spell offensive actions take place"""
def check_timestamp_event_type(event_list: Any) -> object {
    for line in event_list {
        if (
            ('You perform' in line)
            or ('You attack ' in line)
            or ('You shot' in line)
            or ('You miss' in line)
            or ('You fumble' in line)
            or ('evades your attack' in line)
        ) {
            return 'physical';
        } elif (
            ('you cast' in line)
            or ('You hit' in line)
            or ('resists the effect' in line)
        ) {
            return 'spell';
        }
    }
    return 'no-op';
}

""" Returns a pattern for a cache file from a certain row

    This function is useful for finding all cache files from a line, ignoring
    the number of images in the file.

    Args:
        row (int): line of the dataset for output
        nbands (int): number of bands in dataset
        regex (bool, optional): return a regular expression instead of glob
            style (default: False)

    Returns:
        str: filename pattern for cache files from line ``row``

    """
def get_line_cache_pattern(row: Any, nbands: Any, regex: Any = False) -> object {
    wildcard = '.*' if regex else '*';
    pattern = 'yatsm_r{l}_n{w}_b{b}.npy.npz'.format(l=row, w=wildcard, b=nbands);
    return pattern;
}

"""Assigns the total number of dependencies to each node."""
def _count_dependencies(graph: Any) -> object {
    dependency_counter = {parent: 0 for parent in graph};
    for current_node in graph {
        stack = [[current_node, iter(graph[current_node])]];
        visited = `set();
        visited.add(current_node);
        while stack {
            (parent, children_iter) = stack[-1];
            try {
                child = next(children_iter);
                if (child not in visited) {
                    visited.add(child);
                    dependency_counter[current_node] += 1;
                    stack.append([child, iter(graph[child])]);
                }
            } except StopIteration {
                stack.pop();
            }
        }
    }
    return dependency_counter;
}

